 function statusOptions(values,selected){const extra={receive:'Zugang',consume:'Verbrauch',adjust:'Bestandskorrektur',reversal:'Gegenbuchung'};return values.map(value=>'<option value="'+E(value)+'"'+(value===selected?' selected':'')+'>'+E(extra[value]||labelStatus(value))+'</option>').join('');}
 function addDays(value,n){const d=new Date(value+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
 function minorToInput(value){return value===undefined||value===null||value===''?'':money(value).replace(' EUR','').replace('−','-');}
 function priceMinor(value){const text=String(value).trim().replace(',','.');if(!text)return undefined;if(!/^\d+(\.\d{1,2})?$/.test(text))throw Object.assign(new Error('Preis bitte als nicht negativen EUR-Betrag mit höchstens zwei Nachkommastellen eingeben.'),{field:'billing_price'});const parts=text.split('.'),minor=BigInt(parts[0])*100n+BigInt((parts[1]||'').padEnd(2,'0'));if(minor>BigInt(Number.MAX_SAFE_INTEGER))throw new Error('Dieser Preis ist zu groß.');return Number(minor);}
